smallest_range_covering_elements_from_k_.brute:
covers(low, high): true if every list has a value in [low, high]
values = sorted distinct values across all lists
best = none
for each a in values (range start):
    for each b from a onward (range end):
        if covers(values[a], values[b]):   (the first covering end is the best for this start)
            if best is none or values[b] - values[a] < width of best: best = [values[a], values[b]]
            break
return best

minimum_number_of_refueling_stops.brute:
best = -1
for each subset of stations:
    fuel = start_fuel, stops = 0, arrived = true
    for each station i in the subset, in order:
        if fuel < position of station i: arrived = false, break   (ran dry before it)
        fuel = fuel + gas of station i, stops = stops + 1
    if arrived and fuel >= target:
        if best < 0 or stops < best: best = stops
return best

course_schedule_iii.brute:
ordered = (deadline, duration) pairs sorted by deadline
best = 0
for each subset of the courses:
    time = 0, count = 0, feasible = true
    for each course i in the subset, in deadline order:
        time = time + duration of i, count = count + 1
        if time > deadline of i: feasible = false, break
    if feasible: best = max(best, count)
return best

meeting_rooms_iii.brute:
sort meetings by start
free_at = array of n zeros, count = array of n zeros
for each (start, end):
    room = lowest-numbered room with free_at[room] <= start, or -1
    if room < 0:
        room = the room with the smallest free_at (ties: lowest number)
        end = free_at[room] + (end - start)   (delayed meeting keeps its duration)
    free_at[room] = end
    count[room] = count[room] + 1
return the index of the largest count

the_skyline_problem.optimal:
events = (left, -height, right) per building plus (right, 0, 0) end markers, sorted
live = max-heap of (height, right) seeded with (0, infinity)
out = [], previous = 0
for each event (x, neg_height, right):
    while the tallest live building has right <= x: pop it   (lazy removal)
    if this is a start event: push (height, right)
    tallest = height at the top of live
    if tallest != previous:
        append [x, tallest] to out
        previous = tallest
return out
